entries[122146] = { ["name"] = "Dampfhutpilze", ["text"] = "Questgegenstand\n\"Kräftig und aromatisch.\"" }
entries[122147] = { ["name"] = "Aufzeichnungen des grinsenden Tolg", ["text"] = "Wird beim Aufheben gebunden\n\"Diese Schriften befassen sich mit der Suche des Klans des Lachenden Schädels nach dem legendären Schädelgreifer.\"\n<Zum Lesen rechtsklicken>" }
entries[122150] = { ["name"] = "Der schweigende Schädel", ["text"] = "Questgegenstand\n\"Die verfluchte Schädelmaske ist verantwortlich für Schädelgreifers Wahnsinn.\"" }
entries[122153] = { ["name"] = "Aufgeladenes Manajuwel", ["text"] = "Questgegenstand\n\"Knistert vor Leyenergie.\"" }
