entries[122159] = { ["name"] = "Auge von Antonidas", ["text"] = "Questgegenstand\n\"Von Erzmagier Antonidas vorhergesagt, die Leylinien zum Herz von Dalaran zu führen, auf dass die Kirin Tor auf ewig jeglicher Nutzung von Magie auf Azeroth gewahr werden würden.\"" }
