entries[122275] = { ["name"] = "Sonnenberührte Feder von Rukhmar", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Das Büschel Daunenfedern einer Sonnensturmkrähe verleiht einem Anhänger atemberaubende Geschwindigkeit.\n\"Das Büschel Daunenfedern einer Sonnensturmkrähe verleiht einem Anhänger atemberaubende Geschwindigkeit.\"\nVerkaufspreis:" }
