entries[122529] = { ["name"] = "Schreckenspiratenring", ["text"] = "Erbstück Aufwertungsstufe: 0/0\nWird an Kriegsmeute gebunden\nEinzigartig anlegbar\nFinger\n+9 Ausdauer\nErhöht Eure kritische Trefferwertung um + 18.\nErhöht Eure Tempowertung um + 10.\n29 ( 29)\n\nOrnat der sagenhaften Abenteurer (0/7)\nErbstückbrustrüstung\nErbstückhelm\nErbstückschultern\nErbstückumhang\nErbstückbeinrüstung\nErbstückkette\nErbstückring\n(2) Set : Verringert den Verbrauch des Ruhebonus um 30%.\n(3) Set : Erhöht in Außengebieten, in normalen Dungeons und auf Schlachtfeldern Eure Regeneration außerhalb des Kampfes.\n(5) Set : Ein Stufenaufstieg löst eine 'Explosion des Wissens' aus, die Gegnern in der Nähe 1126 Heiligschaden zufügt und Eure Hauptwert 2 Min. lang um 40% erhöht. Das Besiegen von Gegnern verlängert diesen Effekt um bis zu zusätzlich 2 Min.\n(6) Set : Verringert den Verbrauch des Ruhebonus um zusätzlich 30%.\n\nQuest:\nAnglerwettbewerb im Schlingendorntal" }
entries[122530] = { ["name"] = "Geerbtes Mal der Tyrannei", ["text"] = "Erbstück Aufwertungsstufe: 0/0\nWird an Kriegsmeute gebunden\nEinzigartig\nSchmuck\n+11 Ausdauer\nBenutzen: Erhöht die maximale Gesundheit 15 Sek. lang um 1057 . Teilt eine Abklingzeit mit anderen Schmuckstücken des Kampfmeisters. (2 Min Abklingzeit)\n29 ( 29)\n\nVerkäufer:\nEstelle Gendry\nZone:\nOrgrimmar - Tor von Orgrimmar\n\nVerkäufer:\nKrom Starkarm\nZone:\nEisenschmiede - Halle der Forscher" }
