entries[122584] = { ["name"] = "Wild auf Wildlinge", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lässt einen Anhänger die Eigenschaft 'Wildling' erlernen, die die Erfolgschance erhöht, wenn ein Wildtier an der Mission teilnimmt. Dabei wird eine existierende Eigenschaft ersetzt.\n\"Leitfaden für angehende Wildlingflüsterer.\"\nVerkaufspreis:" }
entries[122589] = { ["name"] = "Umwandlung von Ogerportalsteinen", ["text"] = "\"Magier können Ogerportalsteine in Apexiskristalle und Missionsabschlussberichte für Eure Garnison umwandeln.\"" }
