entries[122597] = { ["name"] = "Verzauberter Leitstein", ["text"] = "Questgegenstand" }
entries[122599] = { ["name"] = "Foliant der magischen Elemente", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Bringt Euch die Transmutationsrezepte für die magischen Elemente Draenors bei.\nBenötigt Alchemie von Draenor\n(1)" }
entries[122600] = { ["name"] = "Rezept: Wildblut", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Transmutation von Wildblut.\nBenötigt Alchemie von Draenor\n(1)\n\nWildblut\nHandwerksmaterial\n\"Aus der Scheune der Garnison oder von Alchemisten hergestellt. Kann im Auktionshaus gekauft und verkauft werden.\"\nVerkaufspreis:\nBenötigt Alchemischer Katalysator (50), Sichelöl (7)" }
entries[122601] = { ["name"] = "Stein des Windes", ["text"] = "Rang 1 von 6\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)\nSchmuck\n+ 6 Vielseitigkeit\nAnlegen: Ihr habt eine Chance, bei hervorgerufener Heilung oder verursachtem Schaden Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 23 zu erhöhen. Es wird stets Euer höchster Wert gewählt. (Procchance: 35%, 55s Abklingzeit)\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie von Draenor\n(1)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:" }
entries[122602] = { ["name"] = "Stein der Erde", ["text"] = "Rang 2 von 6\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)\nSchmuck\n+ 6 Vielseitigkeit\nAnlegen: Ihr habt eine Chance, bei hervorgerufener Heilung oder verursachtem Schaden Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 23 zu erhöhen. Es wird stets Euer höchster Wert gewählt. (Procchance: 35%, 55s Abklingzeit)\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie von Draenor\n(1)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:" }
entries[122603] = { ["name"] = "Stein des Wassers", ["text"] = "Rang 3 von 6\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)\nSchmuck\n+ 6 Vielseitigkeit\nAnlegen: Ihr habt eine Chance, bei hervorgerufener Heilung oder verursachtem Schaden Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 23 zu erhöhen. Es wird stets Euer höchster Wert gewählt. (Procchance: 35%, 55s Abklingzeit)\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie von Draenor\n(1)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:" }
entries[122604] = { ["name"] = "Stein des Feuers", ["text"] = "Rang 4 von 6\nWird beim Anlegen gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)\nSchmuck\n+ 6 Vielseitigkeit\nAnlegen: Ihr habt eine Chance, bei hervorgerufener Heilung oder verursachtem Schaden Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 23 zu erhöhen. Es wird stets Euer höchster Wert gewählt. (Procchance: 35%, 55s Abklingzeit)\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:" }
entries[122605] = { ["name"] = "Foliant der Steine", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Herstellung der vier Elementarsteine Draenors, mächtige Schmuckstücke, die an den Alchemisten gebunden sind.\nBenötigt Alchemie von Draenor\n(1)" }
