entries[122607] = { ["name"] = "Wilde Tasche der Kooperation", ["text"] = "Wird beim Aufheben gebunden\n\"Randvoll mit Gold, Verstärkungsrunen und Ausrüstungsmarken.\"\n<Zum Öffnen rechtsklicken>" }
