entries[122677] = { ["name"] = "Tasche voller Gold", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Öffnet den Beutel." }
entries[122679] = { ["name"] = "Vrykulwaffen", ["text"] = "Questgegenstand\n\"Eine Waffe aus unzivilisierteren Zeiten.\"" }
entries[122681] = { ["name"] = "Hecktiefs Haustierführer", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Öffnet das Buch. Kann nur in Azsuna verwendet werden. (2 Min Abklingzeit)\n\"Dieses Tagebuch wurde von Sklaven verfasst und listet die Schwächen und Stärken von Hecktiefs verschiedenen Gladiatoren auf.\"" }
entries[122685] = { ["name"] = "Kletterschuhe", ["text"] = "Questgegenstand" }
entries[122686] = { ["name"] = "Gefetteter Umhang", ["text"] = "Questgegenstand" }
entries[122696] = { ["name"] = "Seeskorpionoschi", ["text"] = "Wird beim Aufheben gebunden\n\"Vorsicht. Seinen Scheren ist schon so manch ein Finger zum Opfer gefallen. Ein Fang, der nur Meisteranglern mit der Hilfe von Nat Pagle gelingt.\"" }
entries[122699] = { ["name"] = "Okunas Nachricht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n45 ( 45)\n\"Die Nachricht in dieser Flasche ist ein Hilfegesuch von jemandem namens Okuna Langhauer. Anscheinend werden er und seine Schiffskameraden von einem Meeresriesenklan als Sklaven gehalten.\"" }
entries[122700] = { ["name"] = "Tragbares Audiofon", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Stellt Euer tragbares Audiofon auf. (1 Min Abklingzeit)\n\"Ein winziges Abspielgerät, das magisch auf den Besitzer abgestimmt ist.\"" }
entries[122701] = { ["name"] = "Hochexplosivgranaten", ["text"] = "Questgegenstand" }
entries[122702] = { ["name"] = "Sicherheitsbehälter", ["text"] = "Questgegenstand" }
entries[122703] = { ["name"] = "Chopper mit Chauffeur", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nHeuert einen Chauffeur an, der Euch durch die Gegend kutschiert.\n\"Heuert Euren eigenen Chauffeur an.\"\n\n\"Wozu selbst steuern, wenn man ebenso gut jemanden dafür bezahlen kann?\"\nErfolg:\nErbstückhorter" }
entries[122704] = { ["name"] = "Elothirs Zweig", ["text"] = "Questgegenstand\nBenutzen: Entfernt den Fluch des Steins von den versteinerten Kreaturen Thas'talahs. (6 Sek. Abklingzeit)" }
entries[122705] = { ["name"] = "Pläne: Rätsel des Echtstahls", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die uneingeschränkte Herstellung von Echtstahlbarren.\nBenötigt Schmiedekunst von Draenor (1)\n\nEchtstahlbarren\nWird beim Aufheben gebunden\nHandwerksmaterial\nVerkaufspreis:\nBenötigt Urgeist , Echteisenerz (5), Schwarzfelserz (5)" }
entries[122706] = { ["name"] = "Anpassungsmedaillon des wilden Gladiators", ["text"] = "Saison 1 von Warlords\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 11 Vielseitigkeit\nBenötigt eine Allianz-Rasse\nBenutzen: Entfernt alle bewegungseinschränkenden Effekte und Kontrollverlusteffekte. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[122707] = { ["name"] = "Anpassungsmedaillon des wilden Gladiators", ["text"] = "Saison 1 von Warlords\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 11 Vielseitigkeit\nBenötigt eine Horde-Rasse\nBenutzen: Entfernt alle bewegungseinschränkenden Effekte und Kontrollverlusteffekte. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[122708] = { ["name"] = "Anpassungsmedaillon des wilden Kämpfers", ["text"] = "Saison 1 von Warlords\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 10 Vielseitigkeit\nBenötigt eine Allianz-Rasse\nBenutzen: Entfernt alle bewegungseinschränkenden Effekte und Kontrollverlusteffekte. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[122709] = { ["name"] = "Anpassungsmedaillon des wilden Kämpfers", ["text"] = "Saison 1 von Warlords\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 10 Vielseitigkeit\nBenötigt eine Horde-Rasse\nBenutzen: Entfernt alle bewegungseinschränkenden Effekte und Kontrollverlusteffekte. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[122710] = { ["name"] = "Rezept: Uralchemie", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die uneingeschränkte Herstellung von alchemischen Katalysatoren.\nBenötigt Alchemie von Draenor\n(1)\n\nAlchemischer Katalysator\nHandwerksmaterial\n\"Beschleunigt Reaktionen, die sonst Tausende von Jahren benötigen würden, und ist daher unerlässlich für die Alchemie auf Draenor.\"\nBenötigt Urgeist , Feuerwurz (2), Gorgrondfliegenfalle (2), Nagrandpfeilkelch (2), Sternenblume (2), Taladororchidee (2)" }
entries[122711] = { ["name"] = "Formel: Temporale Bindung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die uneingeschränkte Herstellung von temporalen Kristallen.\nBenötigt Verzauberkunst von Draenor (1)\n\nZerbrochener temporaler Kristall\nBenutzen: Fügt 10 zerbrochene temporale Kristalle zu einem temporalen Kristall zusammen.\nHandwerksmaterial\nBenötigt Urgeist , Glitzernder Splitter" }
entries[122712] = { ["name"] = "Bauplan: Urkonstruktion", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die uneingeschränkte Herstellung von Getriebefederteilen.\nBenötigt Ingenieurskunst von Draenor (1)\n\nGetriebefederteile\nWird beim Aufheben gebunden\nHandwerksmaterial\n\"Diese Teile sind unglaublich anpassbar und von Ingenieuren bei Reparaturen hochgeschätzt.\"\nVerkaufspreis:\nBenötigt Urgeist , Schwarzfelserz (5), Echteisenerz (5)" }
entries[122713] = { ["name"] = "Technik: Der Geist des Krieges", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die uneingeschränkte Herstellung von Kriegsbemalung.\nBenötigt Inschriftenkunde von Draenor (1)\nVerkaufspreis:\nKriegsbemalung\nWird beim Aufheben gebunden\nHandwerksmaterial\nBenötigt Urgeist , Himmelblaue Pigmente (4)" }
entries[122714] = { ["name"] = "Vorlage: Urjuwelierskunst", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die uneingeschränkte Herstellung von Taladitkristallen.\nBenötigt Juwelierskunst von Draenor\n(1)\n\nTaladitkristall\nWird beim Aufheben gebunden\nHandwerksmaterial\n\"Ein vielseitiger, im Labor erschaffener Edelstein, der in vielen Juwelierskunstvorlagen Draenors Verwendung findet.\"\nBenötigt Urgeist , Schwarzfelserz (5), Echteisenerz (5)" }
entries[122715] = { ["name"] = "Muster: Lederhandwerk der Ahnen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die uneingeschränkte Herstellung von poliertem Leder.\nBenötigt Lederverarbeitung von Draenor (1)\n\nPoliertes Leder\nWird beim Aufheben gebunden\nHandwerksmaterial\n\"Belastbar und geschmeidig. Wird bei der Lederverarbeitung in Draenor verwendet.\"\nVerkaufspreis:\nBenötigt Urgeist , Rohes Tierleder (10)" }
entries[122716] = { ["name"] = "Muster: Urweberei", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die uneingeschränkte Herstellung von Hexenzwirnstoff.\nBenötigt Schneiderei von Draenor (1)\n\nHexenzwirnstoff\nWird beim Aufheben gebunden\nHandwerksmaterial\n\"Zu feinem Stoff gewebtes Fell, das als Grundlage für die meisten Schneidereiprodukte in Draenor dient.\"\nVerkaufspreis:\nBenötigt Urgeist , Prächtiges Fell (10)" }
entries[122718] = { ["name"] = "Klirrendes Geschenk", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[122719] = { ["name"] = "Mysteriöser Runenstein", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Ein seltsam leuchtender Stein. Er scheint nicht von den Harpyien erschaffen worden zu sein.\"" }
entries[122720] = { ["name"] = "Vrykulhelm", ["text"] = "Questgegenstand\n\"Der Helm scheint von einer großen Axt in zwei Stücke zerteilt worden zu sein.\"" }
entries[122721] = { ["name"] = "Vrykulschild", ["text"] = "Questgegenstand\n\"Dieser Schild sieht aus, als hätte er viele Schlachten gesehen.\"" }
entries[122742] = { ["name"] = "Klingenknochenhaken", ["text"] = "Benutzen: Bringt einen rasiermesserscharfen Dorn an Eurer Angelrute an, der 1 Stunde lang bestehen bleibt und automatisch sämtliche Fische filetiert, die Ihr fangt.\nBenötigt Angeln (50)\nVerkaufspreis:" }
entries[122743] = { ["name"] = "Gaijuperle", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Blickt tief in die Reflektion in der Perle. Kann nur unter Wasser in Draenor verwendet werden. (30 Min Abklingzeit)" }
entries[122746] = { ["name"] = "Kopf von Than Sturmhimmel", ["text"] = "Questgegenstand" }
