entries[123857] = { ["name"] = "Runenbeutel", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält Verstärkungsrunen für Eure aktuelle Beutespezialisierung.\"\n<Zum Öffnen rechtsklicken>" }
entries[123858] = { ["name"] = "Schriftrollenbehälter mit Umschulungszertifikat für Anhänger", ["text"] = "Wird beim Aufheben gebunden\n\"Die Aufzeichnungen von Klingenmeister Yozshura, sie enthalten all seine Lehren und Weisheiten.\"\n<Zum Öffnen rechtsklicken>" }
