entries[123866] = { ["name"] = "Entladener Kern einer Höllenbestie", ["text"] = "Questgegenstand\nDauer: 1 Stunde (Realzeit)\nBenutzen: Kombiniert 5 entladene Kerne von Höllenbestien, um einen Höllenbestiendiener zu beschwören, der Euch für kurze Zeit beschützt." }
entries[123867] = { ["name"] = "Roarks Werftbaupläne", ["text"] = "Questgegenstand\n\"Maßangaben und detaillierte Pläne für Anlagen, die Schiffe beinah jeder Form und Größe beherbergen können.\"" }
