entries[123880] = { ["name"] = "Lord Hal'sharas Grabmal", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Nach Stunden akribischer Nachforschung hat Lunara die Position eines Grabes entdeckt, das aller Wahrscheinlichkeit nach wertvolle Relikte enthält.\"" }
