entries[123974] = { ["name"] = "Zügel der verderbten Unheilschwinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man eine verderbte Unheilschwinge beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört eine reitbare verderbte Unheilschwinge oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Orden der Erwachten\n- Freundlich\n\n\"Ein Bad in Dämonenblut hat die Aggressivität dieser verderbten Kreaturen extrem gesteigert, weshalb sie sich in Gefangenschaft nicht selten gegenseitig töten.\"\nVerkäufer:\nDämmerungssucher Krisek\nZone:\nTanaandschungel\nFraktion:\nOrden der Erwachten - Freundlich\nKosten:\n150.000" }
