entries[124030] = { ["name"] = "Die Messerfaust", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nEinhändig Faustwaffe\n4 - 6 Schaden Geschwindigkeit 2.60\n(1.9 Schaden pro Sekunde)\n+2 [Beweglichkeit oder Stärke]\n+3 Ausdauer\nHaltbarkeit 65 / 65\nAnlegen: Eure Angriffe haben eine Chance, Euer Tempo für 10 Sek. um 32 zu erhöhen. (Procchance: 15%, 45s Abklingzeit)\nVerkaufspreis:" }
