entries[124045] = { ["name"] = "Stinkende Moschusdrüse", ["text"] = "Tanaandschungel\nWird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Kombiniert 10 Moschusdrüsen und versprüht ihren Duft in der Luft, um den Düsterschwingenalpha anzulocken!\n\"Wenn Ihr Euch damit einsprüht, könnte das eine wirklich große Düsterschwinge anlocken!\"" }
entries[124049] = { ["name"] = "Handgefertigte Leysteinstulpen", ["text"] = "Questgegenstand\nEinzigartig\nDauer: 1 sek. (Realzeit)\n\"Schön, perfekt, vortrefflich.\"" }
entries[124051] = { ["name"] = "Verbrannte Explosionsüberreste", ["text"] = "Questgegenstand\nEinzigartig\n\"Der Leystein ist beim Auftragen des Fluxes explodiert.\"" }
entries[124055] = { ["name"] = "Runenverzierte Schriftrolle", ["text"] = "Questgegenstand\nBenutzen: Lest mich.\n\"Mystische Runen schweben dicht über dem Pergament.\"" }
entries[124069] = { ["name"] = "Teufelsstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nDauer: 30 min\nBenutzen: Eure Angriffe haben eine Chance, zusätzliche Teufelseffekte auszulösen. Funktioniert nicht bei Spielercharakteren über Stufe 49. (5 Min Abklingzeit)\n\"Dieser scheinbar gewöhnliche Stein pulsiert vor Teufelsenergie.\"" }
entries[124070] = { ["name"] = "Kugel der Eredar", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Erhöht 2 Min. lang die Werte des Zaubernden um 25% sowie seinen Schaden um 25%. (5 Min Abklingzeit)\n\"Die Kugel fühlt sich warm an.\"" }
entries[124071] = { ["name"] = "Schattenstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lässt Euch in die Schatten tauchen. Während der Effekt aktiv ist, seid Ihr unsichtbar und könnt von Gegnern nicht als Ziel gewählt werden. Hält 1 Min. lang an.\n\nDer Effekt wird abgebrochen, wenn Ihr selbst Aktionen ausführt. Funktioniert nicht bei Spielercharakteren über Stufe 49. (5 Min Abklingzeit)\n\"Schatten entfliehen der zerbrochenen Mitte dieses kleinen Steins.\"" }
entries[124072] = { ["name"] = "Zauberschutz von Sargeras", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Regeneriert alle 5 Sek. 2% Gesundheit und verringert sämtlichen erlittenen Schaden um 10%. Hält 10 Min. lang an. Funktioniert nicht bei Spielercharakteren über Stufe 49. (5 Min Abklingzeit)\n\"Schutz.\"" }
entries[124075] = { ["name"] = "Illidari Warglaives [update icon]", ["text"] = "Questgegenstand\n\"Die Schneide ist noch immer so scharf, wie an dem Tag, an dem Ihr sie zum letzten Mal im Schwarzen Tempel geschliffen habt.\"" }
entries[124084] = { ["name"] = "Blutgesättigte Klinge", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Schwert\n5 - 8 Schaden Geschwindigkeit 2.60\n(2.5 Schaden pro Sekunde)\nVerkaufspreis:" }
entries[124089] = { ["name"] = "Bissiger Kriegsroboschreiter", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren bissigen Kriegsroboschreiter oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Ausgestattet mit einem auf dem Kopf montierten Eichhörnchenvernichter 9000.\"\nVerkäufer:\nNekrolord Sipe\nZone:\nSturmwind\nKosten:\n1" }
entries[124093] = { ["name"] = "Geringes Herausforderungstotem der Schwarzfänge", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Fordert einen geringeren Champion der Schwarzfänge in der Arena in Fang'rila heraus. (10 Sek. Abklingzeit)\n\"Wird in den Kampfritualen der Schwarzfänge verwendet, um einen Saberon herauszufordern.\"" }
