entries[124095] = { ["name"] = "Mächtiges Herausforderungstotem der Schwarzfänge", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Fordert den größten Champion der Schwarzfänge in der Arena in Fang'rila heraus. (10 Sek. Abklingzeit)\n\"Wird in den Kampfritualen der Schwarzfänge verwendet, um den obersten Champion herauszufordern.\"" }
