entries[124154] = { ["name"] = "Handschuhe des Arkanrats", ["text"] = "Wird beim Aufheben gebunden\nHände Stoff\n2 Rüstung\n+3 Intelligenz\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 4.\nHaltbarkeit 55 / 55\nKlassen: Magier\nGewandung des Arkanrats (0/5)\nHandschuhe des Arkanrats\nGugel des Arkanrats\nPantalons des Arkanrats\nRobe des Arkanrats\nMantelung des Arkanrats\nAltes Set: Bonus ist nicht aktiv\n(2) Set Arkan: 'Arkane Geschosse' hat eine Chance von 35%, eine Zeitanomalie zu öffnen, die einen zufälligen Helden der Vergangenheit herbeiruft, der Euch 10 Sek. lang im Kampf unterstützt. (Procchance: 35%)\n(2) Set Feuer: 'Pyroschlag' hat eine Chance von 25%, einen feurigen Phönix zu beschwören, der dem Ziel zusätzlichen Feuerschaden zufügt. (Procchance: 25%)\n(2) Set Frost: 'Wasserstrahl' aktiviert automatisch 'Hirnfrost'.\n(4) Set Arkan: Jeder der Helden, die Ihr mit 'Zeitanomalie' beschwört, erhöht den von Euch verursachten Schaden um 12%, bis er wieder verschwindet.\n(4) Set Feuer: Wenn der Phönix heraufbeschworen wurde, erhaltet Ihr 15 Sek. lang 6% Zauberschaden und 6% Zaubertempo.\n(4) Set Frost: Erhöht die Dauer von 'Wasserstrahl' um 10 Sek. und erhöht die maximale Aufladungszahl von 'Eisige Finger' um 2.\nVerkaufspreis:" }
entries[124155] = { ["name"] = "Handwickel der Andacht", ["text"] = "Wird beim Aufheben gebunden\nHände Stoff\n2 Rüstung\n+3 Intelligenz\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 55 / 55\nKlassen: Priester\nGewandung der Frömmigkeit (0/5)\nHandwickel der Andacht\nGugel der Andacht\nGamaschen der Andacht\nGewandung der Andacht\nMantelung der Andacht\nAltes Set: Bonus ist nicht aktiv\n(2) Set Disziplin: Euer Schaden und Eure Heilung von 'Sühne' werden jedes Mal, wenn der Zauber Schaden verursacht oder heilt, 15 Sek. lang um 4% erhöht. Dieser Effekt ist bis zu 6-mal stapelbar.\n(2) Set Heilig: Erhöht Euer Tempo 15 Sek. lang um 2%, wenn 'Gebet der Besserung' überspringt. Dieser Effekt ist bis zu 3-mal stapelbar.\n(2) Set Schatten: Verringert die Abklingzeit von 'Schattengeist' um 30 Sek. und die Abklingzeit von 'Geistbeuger' um 10 Sek.\n(4) Set Disziplin: Jedes Mal, wenn Euer Zauber 'Sühne' ein Ziel heilt oder diesem Schaden zufügt, besteht eine Chance von 50%, einen weiteren Verbündeten in der Nähe Eures Ziels zu heilen.\n(4) Set Heilig: Jedes Mal, wenn 'Gebet der Besserung' überspringt, besteht eine Chance von 10%, dass der Effekt sich aufteilt und ein zusätzliches Ziel in der Nähe heilt.\n(4) Set Schatten: Wenn Euer Schattengeist oder Geistbeuger stirbt, erhaltet Ihr 'Vorahnung', wodurch Eure kritische Trefferchance, Euer Tempo und Eure Meisterschaft 15 Sek. lang um 108 erhöht werden.\nVerkaufspreis:" }
entries[124156] = { ["name"] = "Handschuhe des Todesröchlers", ["text"] = "Wird beim Aufheben gebunden\nHände Stoff\n2 Rüstung\n+3 Intelligenz\n+5 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 55 / 55\nKlassen: Hexenmeister\nOrnat des Todesröchlers (0/5)\nHandschuhe des Todesröchlers\nMaske des Todesröchlers\nGamaschen des Todesröchlers\nRobe des Todesröchlers\nSchulterpolster des Todesröchlers\nAltes Set: Bonus ist nicht aktiv\n(2) Set Gebrechen: Jedes Mal, wenn 'Blutsauger' oder 'Seelendieb' Schaden verursacht, besteht eine Chance von 10%, dass Euer nächster Einsatz von 'Instabiles Gebrechen' keinen Seelensplitter aufzehrt. (Procchance: 10%)\n(2) Set Dämonologie: Euer 'Schattenblitz' erhöht den von Euren Dämonen verursachten Schaden 15 Sek. lang um 1%. Dieser Effekt ist bis zu 5-mal stapelbar.\n(2) Set Zerstörung: Verringert die Zauberzeit Eures Zaubers 'Chaosblitz' um 0.5 Sek. und erhöht seinen Schaden um 2%.\n(4) Set Gebrechen: Wenn 'Instabiles Gebrechen' Schaden verursacht, besteht eine Chance von 10%, dass Euer Schaden für 5 Sek. um 10% erhöht wird. (Procchance: 10%)\n(4) Set Dämonologie: Wenn Eure Wildwichtel 'Teufelsfeuerblitz' einsetzen, besteht eine Chance von 2%, dass ein Dämon aus der Leere beschworen wird, der Euch im Kampf unterstützt.\n(4) Set Zerstörung: 'Chaosblitz' hat eine Chance von 12%, keinen Seelensplitter zu verbrauchen.\nVerkaufspreis:" }
