entries[124225] = { ["name"] = "Seelenkondensator", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+4 Beweglichkeit\nKlassen: Jäger , Schurke , Schamane , Mönch , Druide , Dämonenjäger\nAnlegen: Eure Nahkampfangriffe gewähren eine Chance, 10 Sek. lang 'Geistübergang' auszulösen. Solange Ihr ein Geist seid, wird Euer verursachter Schaden gespeichert. Wenn dieser Effekt endet, erlangt Ihr Eure Körperlichkeit wieder und fügt allen Gegnern im Umkreis von 10 Metern (100 + 28 / 100)% des gespeicherten Schadens zu, der gleichmäßig aufgeteilt wird. (Ungefähr 1.00 Auslösungen pro Minute)\nVerkaufspreis:" }
